const config = {
  dedupe_ttl_days: 7,
  cache_ttl_minutes: 30,
  max_items_total: 25,
  min_score: 10,
  enable_llm_summary: true,
  ZAI_API_KEY: $env.ZAI_API_KEY || '',
  ZAI_BASE_URL: $env.ZAI_BASE_URL || 'https://api.z.ai/api/paas/v4',
  ZAI_MODEL: $env.ZAI_MODEL || 'glm-5'
};

const rss_urls = [
  'https://feeds.bbci.co.uk/news/technology/rss.xml',
  'https://www.nasa.gov/rss/dyn/breaking_news.rss'
];

const keywords = ['openai', 'anthropic', 'n8n', 'postgres', 'embeddings'];

return [{ json: { rss_urls, keywords, config } }];

const items = $input.all();
const output = [];

for (const item of items) {
  const feedData = item.json;
  const entries = feedData.items || [];

  for (const entry of entries) {
    output.push({
      json: {
        source: 'rss',
        keyword: null,
        title: entry.title || 'Untitled',
        url: entry.link || entry.guid || '',
        published_at: entry.pubDate || entry.isoDate || null,
        raw_score: 15,
        score: 15,
        summary_raw: entry.contentSnippet || entry.summary || null,
        summary: null,
        meta: { author: entry.creator || null, venue: 'RSS Feed' }
      }
    });
  }
}

return output;

const items = $input.all();
if (!items || items.length === 0) {
  return [{ json: { __empty: true, __stream: 'rss' } }];
}
return items;

const items = $input.all();
if (!items || items.length === 0) {
  return [{ json: { __empty: true, __stream: 'kw' } }];
}
return items;

const allItems = $input.all();
const staticData = this.getWorkflowStaticData('global');
if (!staticData.seen) staticData.seen = {};

const now = Date.now();
const dedupeMs = 7 * 24 * 60 * 60 * 1000;
const minScore = 10;
const maxItems = 25;

for (const url in staticData.seen) {
  if (now - staticData.seen[url] > dedupeMs) delete staticData.seen[url];
}

const validItems = allItems.map(i => i.json).filter(i => !i.__empty);
const candidatesTotal = validItems.length;
const newItems = [];
const stats = { by_source: {}, cached_hits: 0, api_calls: 0, failed_calls: 0 };

for (const item of validItems) {
  if (item.meta?.cached) stats.cached_hits++;
  if (item.meta?.api_calls) stats.api_calls += item.meta.api_calls;
  if (item.meta?.failed_calls) stats.failed_calls += item.meta.failed_calls;
  stats.by_source[item.source] = (stats.by_source[item.source] || 0) + 1;

  if (!staticData.seen[item.url]) {
    staticData.seen[item.url] = now;
    newItems.push(item);
  }
}

const finalItems = newItems.filter(i => i.score >= minScore).sort((a, b) => b.score - a.score).slice(0, maxItems);
const digest = finalItems.map((item, idx) => `${idx + 1}. **${item.title}** (${item.source}) - ${item.url}`).join('\n');

const config = allItems[0]?.json?.config || {};
const keywords = allItems[0]?.json?.keywords || [];

return [{
  json: {
    run_id: $execution.id,
    generated_at: new Date().toISOString(),
    keywords,
    config,
    stats: { candidates_total: candidatesTotal, new_items: newItems.length, final_items: finalItems.length, ...stats },
    items: finalItems,
    digest_markdown: digest
  }
}];

const data = $json;
const topItems = data.items.slice(0, 10);

const content = `Summarize the following ${topItems.length} tech news items briefly (max 15 words each). Return ONLY a JSON object with key 'summaries', an array of objects with 'url' and 'summary' keys.\n` + 
  topItems.map(i => `URL: ${i.url}\nTITLE: ${i.title}\n`).join('\n');

return [{
  json: {
    config: data.config,
    originalData: data,
    body: {
      model: data.config.ZAI_MODEL,
      response_format: { type: 'json_object' },
      messages: [{ role: 'user', content }]
    }
  }
}];

const originalData = $('Prepare LLM Payload').item.json.originalData;
const response = $json;

let finalItems = originalData.items;

if (response?.choices?.[0]?.message) {
  try {
    const content = response.choices[0].message.content;
    const parsed = JSON.parse(content);
    if (parsed.summaries && Array.isArray(parsed.summaries)) {
      const summaryMap = {};
      parsed.summaries.forEach(s => summaryMap[s.url] = s.summary);
      finalItems = finalItems.map(item => ({
        ...item,
        summary: summaryMap[item.url] || item.summary_raw || item.title
      }));
    }
  } catch (e) {
    finalItems = finalItems.map(item => ({ ...item, summary: item.summary_raw || item.title }));
  }
} else {
  finalItems = finalItems.map(item => ({ ...item, summary: item.summary_raw || item.title }));
}

return [{ json: { ...originalData, items: finalItems } }];

const data = $json;
const finalItems = data.items.map(item => ({ ...item, summary: item.summary_raw || item.title }));
return [{ json: { ...data, items: finalItems } }];

const data = $json;
if (!Array.isArray(data.items)) throw new Error('Items is not an array');
data.items.forEach(item => {
  if (!item.url || typeof item.url !== 'string') throw new Error('Invalid URL');
  if (typeof item.score !== 'number') throw new Error('Invalid score');
  const str = JSON.stringify(item);
  if (str.includes('{{')) throw new Error('Detected unescaped handlebars');
});
return [{ json: data }];

const data = $json;
return [{
  json: {
    run_id: data.run_id,
    generated_at: data.generated_at,
    keywords: data.keywords,
    stats: data.stats,
    items: data.items,
    digest_markdown: data.digest_markdown
  }
}];

const staticData = this.getWorkflowStaticData('global');
if (!staticData.cache) staticData.cache = {};

const input = $input.first().json;
const keyword = input.keyword;
const config = input.config;
const ttlMs = (config.cache_ttl_minutes || 30) * 60 * 1000;
const now = Date.now();

const cached = staticData.cache[keyword];

if (cached && (now - cached.ts_epoch_ms < ttlMs)) {
  return [{ json: { keyword, config, cache_hit: true, cached_items: cached.items, cached_hits: (cached.hits || 0), api_calls: 0, failed_calls: 0 } }];
}

return [{ json: { keyword, config, cache_hit: false, cached_hits: 0, api_calls: 0, failed_calls: 0 } }];

const data = $json;
return data.cached_items.map(item => ({
  json: { ...item, meta: { ...item.meta, cached: true, api_calls: 0, failed_calls: 0 } }
}));

const keyword = $('Cache Gate').item.json.keyword;
const data = $json;

if (!data || !data.hits || data.error) {
  return [{ json: { __empty: true, __src: 'hn', meta: { failed_calls: 1 } } }];
}

return data.hits.map(hit => ({
  json: {
    source: 'hn',
    keyword,
    title: hit.title,
    url: hit.url || `https://news.ycombinator.com/item?id=${hit.objectID}`,
    published_at: hit.created_at ? new Date(hit.created_at).toISOString() : null,
    raw_score: (hit.points || 0) + (hit.num_comments || 0),
    score: (hit.points || 0) + (hit.num_comments || 0),
    summary_raw: null,
    summary: null,
    meta: { author: hit.author, venue: 'Hacker News', failed_calls: 0 }
  }
}));

const keyword = $('Cache Gate').item.json.keyword;
const data = $json;

if (!data || !data.query || !data.query.search || data.error) {
  return [{ json: { __empty: true, __src: 'wikipedia', meta: { failed_calls: 1 } } }];
}

return data.query.search.map(hit => ({
  json: {
    source: 'wikipedia',
    keyword,
    title: hit.title,
    url: `https://en.wikipedia.org/wiki/${encodeURIComponent(hit.title.replace(/ /g, '_'))}`,
    published_at: null,
    raw_score: Math.floor((hit.size || 0) / 100),
    score: Math.floor((hit.size || 0) / 100),
    summary_raw: hit.snippet || null,
    summary: null,
    meta: { author: null, venue: 'Wikipedia', failed_calls: 0 }
  }
}));

const keyword = $('Cache Gate').item.json.keyword;
const data = $json;

if (!data || !data.message || !data.message.items || data.error) {
  return [{ json: { __empty: true, __src: 'crossref', meta: { failed_calls: 1 } } }];
}

return data.message.items.map(item => ({
  json: {
    source: 'crossref',
    keyword,
    title: (item.title && item.title[0]) ? item.title[0] : 'Untitled',
    url: item.URL || '',
    published_at: (item['published-print'] && item['published-print']['date-time']) ? item['published-print']['date-time'] : null,
    raw_score: 20 + (item['is-referenced-by-count'] || 0),
    score: 20 + (item['is-referenced-by-count'] || 0),
    summary_raw: null,
    summary: null,
    meta: { author: null, venue: 'Crossref', failed_calls: 0 }
  }
}));

const staticData = this.getWorkflowStaticData('global');
const keyword = $('Cache Gate').item.json.keyword;
const allItems = $input.all();

let failed_calls = 0;
const validItems = allItems
  .map(i => i.json)
  .filter(i => {
    if (i.__empty && i.meta?.failed_calls) {
      failed_calls += i.meta.failed_calls;
      return false;
    }
    return !i.__empty;
  });

staticData.cache[keyword] = {
  ts_epoch_ms: Date.now(),
  items: validItems,
  hits: validItems.length
};

return validItems.map(item => ({
  json: {
    ...item,
    meta: { 
      ...item.meta, 
      cached: false, 
      api_calls: 3, 
      failed_calls: failed_calls 
    }
  }
}));
